Change(genesis='66602cd0dec37d58d03eec9518ca805a7ac38ea912d2b0c366a0b67b4b9f50b6', deps=(), event=Decided(decision='boxturnslink', at=datetime(2026, 9, 14, 0, 0, 0), actor='assistant', title="Only the box's own turns turn a web address into a link", body="In a conversation, a web address becomes a link only in a turn the box wrote: an act's turn or the box's own. A model's turn and a person's turn show an address as plain text. The link opens in a new tab with no opener, and only an http or https address is linked. So the sign-in address of a device-code flow is a link, and an address a model repeats from mail stays inert.", rationale='The model reads mail an attacker controls, and an address it repeats must never become something the owner clicks as if the box had offered it.', supersedes=()))